from fractions import Fraction
from math import comb

def fair_sign_family_p(signs,family_size):
    # OWN one-sided test of many + signs under iid fair +/-1null,predefined family.
    if type(signs) is not tuple or not 1<=len(signs)<=12 or any(type(x) is not int or x not in (-1,1) for x in signs):
        raise ValueError("invalid fair-sign sample")
    if type(family_size) is not int or not 1<=family_size<=100000:
        raise ValueError("invalid fixed family size")
    n=len(signs);positive=sum(x==1 for x in signs)
    raw=Fraction(sum(comb(n,k) for k in range(positive,n+1)),2**n)
    adjusted=min(Fraction(1),family_size*raw)
    return raw,adjusted

raw,adjusted=fair_sign_family_p((1,)*8,20)
print(raw,adjusted,raw<=Fraction(1,20),adjusted<=Fraction(1,20))
# OWN frozen validation selection,then later holdout evaluation,not a fitted model.
validation={"A":(5,5),"B":(10,2),"cash":(0,0)}
holdout={"A":(-2,-2),"B":(-8,0),"cash":(0,0)}
mean=lambda xs:Fraction(sum(xs),len(xs))
winner=min(validation,key=lambda name:(-mean(validation[name]),name))
print(winner,mean(validation[winner]),mean(holdout[winner]))
try:fair_sign_family_p((0,1),20)
except ValueError as error:print(error)
